          answers.push({ label: 'Root x₁', value: fmt(x1), approx: true, primary: true }, { label: 'Root x₂', value: fmt(x2), approx: true, primary: true });
          if (form) answers.push({ label: 'Exact roots', valueTex: `x = ${form.tex}`, copy: `x = ${form.text}` });
